// Extension based on the user's course notes. Original teaching data and examples.
groups.push('Database engineering','Performance & query plans','Warehouse & reporting projects');
moduleDescriptions.push('Create reusable objects and understand their lifetimes.','Read plans and test a hypothesis instead of memorizing speed rules.','Turn raw records into trusted dimensions, facts, and useful reports.');
const warehouseSeed=`
CREATE TABLE bronze_customers(raw_id TEXT,name TEXT,country TEXT,updated_at TEXT);
CREATE TABLE bronze_products(raw_id TEXT,name TEXT,category TEXT,price TEXT);
CREATE TABLE bronze_sales(row_id INTEGER PRIMARY KEY,customer_id TEXT,product_id TEXT,quantity TEXT,sales TEXT,order_date TEXT);
INSERT INTO bronze_customers VALUES(' C001 ',' Alice ','USA','2025-01-01'),('C001',' Alice Nguyen ','US','2025-01-05'),('C002','Ben','GB','2025-01-02'),('C003',' Cara ','UK','2025-01-03'),('C004','Dev','IND','2025-01-04'),('C005','Elena','CA','2025-01-05'),(NULL,'Missing key','US','2025-01-06');
INSERT INTO bronze_products VALUES('P01',' Notebook ','Stationery','12'),(' P02 ','Desk lamp','Home','45'),('P03','Keyboard','Tech','80'),('P04','Headphones','Tech','120');
INSERT INTO bronze_sales VALUES(1,'C001','P01','2','24','2025-01-01'),(2,' C002 ','P03','1','80','2025-01-02'),(3,'C001','P02','1','45','2025-01-15'),(4,'C003','P04','2','240','2025-02-01'),(5,'C004','P03','2','160','2025-02-05'),(6,'C001','P04','1','120','2025-02-15'),(7,'C002','P01','3','36','2025-03-01'),(8,'C003','P02','2','90','2025-03-03'),(9,'C004','P01','0','0','2025-03-05'),(10,'C001','P01','bad','999','2025-03-06'),(11,'C999','P01','1','12','2025-03-07'),(12,'C002','P03','1','80','not-a-date'),(13,'C001','P01','2','999','2025-03-08');
CREATE TABLE dim_customer(customer_key INTEGER PRIMARY KEY,customer_id TEXT UNIQUE,name TEXT,country TEXT);
INSERT INTO dim_customer VALUES(1,'C001','Alice Nguyen','United States'),(2,'C002','Ben','United Kingdom'),(3,'C003','Cara','United Kingdom'),(4,'C004','Dev','India'),(5,'C005','Elena','Canada');
CREATE TABLE dim_product(product_key INTEGER PRIMARY KEY,product_id TEXT UNIQUE,name TEXT,category TEXT,price REAL);
INSERT INTO dim_product VALUES(1,'P01','Notebook','Stationery',12),(2,'P02','Desk lamp','Home',45),(3,'P03','Keyboard','Tech',80),(4,'P04','Headphones','Tech',120);
CREATE TABLE fact_sales(sale_key INTEGER PRIMARY KEY,customer_key INTEGER,product_key INTEGER,quantity INTEGER,sales REAL,order_date TEXT);
INSERT INTO fact_sales SELECT b.row_id,c.customer_key,p.product_key,CAST(b.quantity AS INTEGER),CAST(b.quantity AS INTEGER)*p.price,b.order_date FROM bronze_sales b JOIN dim_customer c ON c.customer_id=TRIM(b.customer_id) JOIN dim_product p ON p.product_id=TRIM(b.product_id) WHERE TRIM(b.quantity)<>'' AND TRIM(b.quantity) NOT GLOB '*[^0-9]*' AND CAST(b.quantity AS INTEGER)>0 AND b.order_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date(b.order_date,'+0 days')=b.order_date;
CREATE TABLE lab_items(id INTEGER PRIMARY KEY,name TEXT NOT NULL,price REAL NOT NULL CHECK(price>=0));
INSERT INTO lab_items VALUES(1,'Notebook',12),(2,'Lamp',45),(3,'Keyboard',80);
CREATE TABLE lab_audit(item_id INTEGER,old_price REAL,new_price REAL);
`;
seed+=warehouseSeed;
datasetCatalog.warehouse={name:'Northstar Retail',role:'Warehouse & analytics engineer',description:'Fictional CRM/catalog/sales extracts and curated star-schema tables. Raw keys, dates, quantities, and sales need validation. One fact row is one sales line.',tables:['bronze_customers','bronze_products','bronze_sales','dim_customer','dim_product','fact_sales']};
datasetCatalog.lab={name:'Disposable Lab',role:'Database engineer',description:'A fresh in-memory database for each run. Write a complete script ending in SELECT. Changes never leave this run; repeat all setup in the same script.',tables:['lab_items','lab_audit']};
Object.assign(schemas,{bronze_customers:['raw_id TEXT · may be missing/unclean','name TEXT','country TEXT · source codes','updated_at TEXT · version timestamp'],bronze_products:['raw_id TEXT · natural product key','name TEXT','category TEXT','price TEXT'],bronze_sales:['row_id INTEGER · source line key','customer_id TEXT','product_id TEXT','quantity TEXT · includes invalid values','sales TEXT · may disagree with quantity × price','order_date TEXT · includes invalid date'],dim_customer:['customer_key INTEGER · surrogate primary key','customer_id TEXT · unique natural key','name TEXT','country TEXT'],dim_product:['product_key INTEGER · surrogate primary key','product_id TEXT · unique natural key','name TEXT','category TEXT','price REAL'],fact_sales:['sale_key INTEGER · one sales line','customer_key INTEGER → dim_customer.customer_key','product_key INTEGER → dim_product.product_key','quantity INTEGER','sales REAL · quantity × catalog price','order_date TEXT'],lab_items:['id INTEGER · primary key','name TEXT · NOT NULL','price REAL · CHECK >= 0'],lab_audit:['item_id INTEGER','old_price REAL','new_price REAL']});
function extension(title,group,dataset,concept,example,tasks,hints,trap,prereq=[],mode='read'){advanced(title,group,dataset,concept,example,tasks,hints,trap,prereq);const l=lessons.at(-1);l.mode=mode;l.grain=group===9?'Respect the sales-line grain and use dimension keys for relationships.':group===7?'Each script starts from a fresh database and must end with a result query.':'Measure a defined result, then inspect the physical strategy.';return l;}
extension('Databases, schemas, tables & keys',0,'shop','SQL is the language; the database engine executes it. Tables contain rows and typed columns. A primary key identifies one row; a foreign key points to another table. SQLite catalogs differ from SQL Server schemas. In this app each worker creates an in-memory SQLite database.','SELECT name,type FROM sqlite_schema\nWHERE type=\'table\' AND name IN(\'customers\',\'products\',\'orders\');',[
 ['Return name and type for the customers, products and orders tables from sqlite_schema.','SELECT name,type FROM sqlite_schema WHERE type=\'table\' AND name IN(\'customers\',\'products\',\'orders\')'],
 ['Return order_id and customer_name by joining orders.customer_id to customers.id for every order.','SELECT o.id AS order_id,c.name AS customer_name FROM orders o JOIN customers c ON c.id=o.customer_id']
],['Metadata describes the database objects.','sqlite_schema is SQLite’s catalog; table relationships use the schema’s id fields.'],'A matching-looking name is not a reliable join key; use the defined identifiers.',[0]);
extension('Logical query processing & row grain',2,'shop','Think FROM/JOIN → WHERE → GROUP BY → HAVING → SELECT → ORDER BY. This is a logical model, not a promise about physical execution. Row expressions preserve rows, aggregates collapse them, and windows add context without collapsing.','SELECT customer_id,SUM(quantity) AS units\nFROM orders WHERE status=\'paid\' GROUP BY customer_id\nHAVING SUM(quantity)>2 ORDER BY units DESC;',[
 ['Return customer_id and units for paid orders grouped by customer; keep groups with units >2. Sort units descending, then customer_id ascending.','SELECT customer_id,SUM(quantity) AS units FROM orders WHERE status=\'paid\' GROUP BY customer_id HAVING SUM(quantity)>2 ORDER BY units DESC,customer_id',true],
 ['Keep every paid order row and return id, customer_id, quantity and customer_units (sum of paid quantity for that customer using a window).','SELECT id,customer_id,quantity,SUM(quantity) OVER(PARTITION BY customer_id) AS customer_units FROM orders WHERE status=\'paid\'']
],['WHERE excludes unpaid rows before either calculation.','GROUP BY reduces rows; SUM OVER(PARTITION BY ...) preserves each paid order.'],'SQLite accepts some alias usages other engines reject. Prefer clear expressions or an outer query for portable SQL.',[10,11,23]);
extension('CAST, text types & NULL arithmetic',2,'lab','CAST changes a value’s representation. SQLite uses type affinity rather than SQL Server’s strict column-type model. CAST alone is not validation: nonnumeric text can become zero. NULL propagates through arithmetic unless a business rule replaces it.','SELECT id,CAST(price AS TEXT) AS price_text FROM lab_items;',[
 ['Return id and price_text by casting price to TEXT for every lab item.','SELECT id,CAST(price AS TEXT) AS price_text FROM lab_items'],
 ['Return id and absolute_gap as ABS(price - 50) for every lab item.','SELECT id,ABS(price-50) AS absolute_gap FROM lab_items']
],['Use CAST(value AS TEXT) for an explicit conversion.','ABS returns magnitude without a negative sign.'],'Do not assume CAST rejects malformed data; validate source text first.',[1]);
extension('NTILE & balanced ranking buckets',5,'stream','NTILE divides an ordered partition into a requested number of buckets. Bucket row counts differ by at most one, with larger buckets first. It may separate equal values; use a deterministic tie-breaker if that is acceptable.','SELECT id,watch_seconds,NTILE(4) OVER(\nORDER BY watch_seconds DESC,id) AS bucket FROM watch_events;',[
 ['Return id, watch_seconds and bucket using NTILE(4), ordered within the window by watch_seconds descending then id.','SELECT id,watch_seconds,NTILE(4) OVER(ORDER BY watch_seconds DESC,id) AS bucket FROM watch_events'],
 ['Return id, viewer_id and bucket using NTILE(2) per viewer, ordered within viewer by watched_at then id.','SELECT id,viewer_id,NTILE(2) OVER(PARTITION BY viewer_id ORDER BY watched_at,id) AS bucket FROM watch_events']
],['NTILE is a window function.','PARTITION BY restarts buckets for each viewer in the second challenge.'],'NTILE creates roughly equal row counts, not equal numeric ranges or tie-preserving ranks.',[22]);
extension('DDL: create, alter & inspect a table',7,'lab','DDL changes structure: CREATE, ALTER, DROP. DML changes rows. Use the disposable lab to try both safely. Keep all statements in one script, ending with SELECT; the next execution starts fresh.','CREATE TABLE practice_people(id INTEGER PRIMARY KEY,name TEXT);\nALTER TABLE practice_people ADD COLUMN city TEXT;\nSELECT name,type FROM pragma_table_info(\'practice_people\');',[
 ['Create practice_people with id INTEGER PRIMARY KEY and name TEXT; add city TEXT with ALTER TABLE. Return name and type from pragma_table_info(\'practice_people\').','CREATE TABLE practice_people(id INTEGER PRIMARY KEY,name TEXT); ALTER TABLE practice_people ADD COLUMN city TEXT; SELECT name,type FROM pragma_table_info(\'practice_people\')'],
 ['Create practice_totals with account_id INTEGER and total REAL. Return name and type from pragma_table_info(\'practice_totals\').','CREATE TABLE practice_totals(account_id INTEGER,total REAL); SELECT name,type FROM pragma_table_info(\'practice_totals\')']
],['CREATE TABLE defines columns and constraints.','SQLite exposes a table-valued pragma_table_info function for this metadata.'],'Schema names and ALTER capabilities differ across engines.',[54],'lab');
extension('DML: INSERT, UPDATE & DELETE',7,'lab','INSERT adds rows; UPDATE changes matching rows; DELETE removes matching rows. Use WHERE to constrain modifications. These exercises touch only disposable copies in memory and are reset on every run.','INSERT INTO lab_items VALUES(4,\'Pen\',8);\nUPDATE lab_items SET price=price+5 WHERE id=1;\nDELETE FROM lab_items WHERE id=2;\nSELECT id,name,price FROM lab_items;',[
 ['Insert lab item (4, Pen, 8); add 5 to price for id=1; delete id=2. Return id, name, price for remaining items.','INSERT INTO lab_items VALUES(4,\'Pen\',8); UPDATE lab_items SET price=price+5 WHERE id=1; DELETE FROM lab_items WHERE id=2; SELECT id,name,price FROM lab_items'],
 ['Double every lab item price below 50, then delete items with price >100. Return id, name, price.','UPDATE lab_items SET price=price*2 WHERE price<50; DELETE FROM lab_items WHERE price>100; SELECT id,name,price FROM lab_items']
],['Use a WHERE clause on each targeted UPDATE and DELETE.','The base table starts with ids 1,2,3 on every execution.'],'An UPDATE without WHERE updates every row; that can be intentional only when the requirement says so.',[58],'lab');
extension('Constraints protect the data contract',7,'lab','PRIMARY KEY identifies rows; NOT NULL requires a value; UNIQUE prevents duplicate values; CHECK enforces a condition. SQLite CHECK passes NULL unless you also use NOT NULL. Foreign-key enforcement needs PRAGMA foreign_keys=ON; the lab enables it.','CREATE TABLE inventory(sku TEXT PRIMARY KEY NOT NULL,\nquantity INTEGER NOT NULL CHECK(quantity>=0));\nINSERT INTO inventory VALUES(\'A\',2);\nSELECT sku,quantity FROM inventory;',[
 ['Create inventory with sku TEXT PRIMARY KEY NOT NULL and quantity INTEGER NOT NULL CHECK(quantity>=0); insert (A,2). Return sku and quantity.','CREATE TABLE inventory(sku TEXT PRIMARY KEY NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>=0)); INSERT INTO inventory VALUES(\'A\',2); SELECT sku,quantity FROM inventory'],
 ['Create contacts with id INTEGER PRIMARY KEY and email TEXT NOT NULL UNIQUE; insert (1,a@example.com) and (2,b@example.com). Return id,email.','CREATE TABLE contacts(id INTEGER PRIMARY KEY,email TEXT NOT NULL UNIQUE); INSERT INTO contacts VALUES(1,\'a@example.com\'),(2,\'b@example.com\'); SELECT id,email FROM contacts']
],['Declare constraints in the CREATE statement, not only in the SELECT.','Try a second run with a negative quantity or repeated email to see the engine reject it.'],'These output exercises are followed by engine-level validation of the requested constraints.',[58],'lab');
extension('Transactions & savepoint recovery',7,'lab','A transaction groups changes. COMMIT keeps them in the current database; ROLLBACK undoes them. SAVEPOINT lets you undo a portion. In this app even committed changes vanish after the run because the entire database is disposable.','BEGIN;\nUPDATE lab_items SET price=price+10;\nROLLBACK;\nSELECT id,price FROM lab_items;',[
 ['Begin a transaction, add 10 to every lab item price, then roll back. Return id and price; all values should be original.','BEGIN; UPDATE lab_items SET price=price+10; ROLLBACK; SELECT id,price FROM lab_items'],
 ['Begin; add 5 to price for id=1; create SAVEPOINT partial; delete id=2; roll back to partial; commit. Return id and price.','BEGIN; UPDATE lab_items SET price=price+5 WHERE id=1; SAVEPOINT partial; DELETE FROM lab_items WHERE id=2; ROLLBACK TO partial; COMMIT; SELECT id,price FROM lab_items']
],['ROLLBACK undoes changes since BEGIN.','ROLLBACK TO partial preserves changes made before that savepoint.'],'A successful statement is not the same as a committed transaction.',[59],'lab');
extension('Views: reusable query definitions',7,'shop','A normal view is a named query definition. It is reusable without storing a snapshot of the result. A view can simplify business logic, but it is not automatically faster or slower than the equivalent query. SQLite views are read-only unless INSTEAD OF triggers support writes.','CREATE VIEW paid_orders AS SELECT id,customer_id,quantity\nFROM orders WHERE status=\'paid\';\nSELECT * FROM paid_orders;',[
 ['Create view paid_orders exposing id, customer_id and quantity for paid orders. Return those columns by selecting the view.','CREATE VIEW paid_orders AS SELECT id,customer_id,quantity FROM orders WHERE status=\'paid\'; SELECT id,customer_id,quantity FROM paid_orders'],
 ['Create view product_totals with category and total_price (sum of price). Return category and total_price from the view.','CREATE VIEW product_totals AS SELECT category,SUM(price) AS total_price FROM products GROUP BY category; SELECT category,total_price FROM product_totals']
],['CREATE VIEW name AS SELECT ... stores the definition.','Query the new view in the same script.'],'A view is an abstraction, not a guarantee of materialization or caching.',[20],'lab');
extension('CTEs, CTAS & temporary tables',7,'shop','A CTE names an expression for one statement. A view persists a definition. CREATE TEMP TABLE ... AS SELECT materializes an intermediate result for the connection. SQL Server uses SELECT ... INTO #temp; that syntax is not SQLite. CTAS does not carry over source constraints.','CREATE TEMP TABLE customer_units AS\nSELECT customer_id,SUM(quantity) AS units FROM orders GROUP BY customer_id;\nSELECT customer_id,units FROM customer_units WHERE units>3;',[
 ['Materialize a TEMP table customer_units with customer_id and total quantity as units. Return customer_id and units for units >3.','CREATE TEMP TABLE customer_units AS SELECT customer_id,SUM(quantity) AS units FROM orders GROUP BY customer_id; SELECT customer_id,units FROM customer_units WHERE units>3'],
 ['Materialize a TEMP table category_prices with category and average price as avg_price. Return category and avg_price for avg_price >30.','CREATE TEMP TABLE category_prices AS SELECT category,AVG(price) AS avg_price FROM products GROUP BY category; SELECT category,avg_price FROM category_prices WHERE avg_price>30']
],['CREATE TEMP TABLE name AS SELECT ... builds the intermediate result.','The materialized result survives statements in this script, not future app runs.'],'SQL Server CTEs do not materialize by default. SQLite can choose different CTE strategies; neither promises a universal speed-up.',[20],'lab');
extension('Triggers & visible audit effects',7,'lab','A trigger runs automatically after a matching event. SQLite row triggers use OLD and NEW values. They can record an audit trail but also create hidden side effects. SQL Server triggers are statement-level and use inserted/deleted tables, so their code is different.','CREATE TRIGGER price_audit AFTER UPDATE OF price ON lab_items\nWHEN OLD.price<>NEW.price BEGIN\nINSERT INTO lab_audit VALUES(NEW.id,OLD.price,NEW.price); END;\nUPDATE lab_items SET price=price+5 WHERE id=1;\nSELECT item_id,old_price,new_price FROM lab_audit;',[
 ['Create a price_audit trigger AFTER UPDATE OF price on lab_items, logging changed prices in lab_audit; add 5 to id=1 price. Return item_id,old_price,new_price from lab_audit.','CREATE TRIGGER price_audit AFTER UPDATE OF price ON lab_items WHEN OLD.price<>NEW.price BEGIN INSERT INTO lab_audit VALUES(NEW.id,OLD.price,NEW.price); END; UPDATE lab_items SET price=price+5 WHERE id=1; SELECT item_id,old_price,new_price FROM lab_audit'],
 ['Create the same trigger, then double prices for all items with price<50. Return item_id,old_price,new_price from lab_audit.','CREATE TRIGGER price_audit AFTER UPDATE OF price ON lab_items WHEN OLD.price<>NEW.price BEGIN INSERT INTO lab_audit VALUES(NEW.id,OLD.price,NEW.price); END; UPDATE lab_items SET price=price*2 WHERE price<50; SELECT item_id,old_price,new_price FROM lab_audit']
],['SQLite provides OLD.price, NEW.price and NEW.id inside the trigger.','CREATE TRIGGER contains BEGIN ... END; keep it intact in the script.'],'A trigger’s side effect is part of the operation. Inspect and test it instead of assuming only one table changed.',[59],'lab');
const procLesson=extension('Stored procedures: parameters & contracts',7,'shop','A SQL Server stored procedure can expose parameters, transactions, and error handling. SQLite has no CREATE PROCEDURE. Here you practice the retrieval contract in SQLite; the separate T-SQL reference shows its SQL Server wrapper. Choose procedures or external orchestration based on the system, not a blanket preference.','SELECT id,customer_id,quantity FROM orders WHERE customer_id=1;',[
 ['For customer_id=1, return id, customer_id and quantity from orders. This practices a procedure’s retrieval contract; no procedure is created in SQLite.','SELECT id,customer_id,quantity FROM orders WHERE customer_id=1'],
 ['For customer_id=2, return id, customer_id and quantity for paid orders only.','SELECT id,customer_id,quantity FROM orders WHERE customer_id=2 AND status=\'paid\'']
],['Treat the parameter as a defined input value.','The SQL Server wrapper is reference-only; run the retrieval query in this app.'],'Parameters should be bound by a client or procedure, not concatenated from untrusted text.',[20]);
procLesson.dialectReference="-- SQL Server / T-SQL reference only; not executable here\nCREATE OR ALTER PROCEDURE dbo.GetCustomerOrders\n    @customer_id int\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT id, customer_id, quantity\n    FROM dbo.orders WHERE customer_id = @customer_id;\nEND;\n-- Execute in SQL Server: EXEC dbo.GetCustomerOrders @customer_id = 1;";
extension('Indexes: observe a real access path',8,'shop','An index offers an access structure at the cost of storage and write work. Use EXPLAIN QUERY PLAN to see SQLite choose SCAN, SEARCH, or a covering index. Plans describe physical access; they are not measured speed. This tiny dataset cannot establish a production performance improvement.','CREATE INDEX idx_orders_customer ON orders(customer_id);\nEXPLAIN QUERY PLAN SELECT id,quantity FROM orders WHERE customer_id=1;',[
 ['Create idx_orders_customer on orders(customer_id), then return id and quantity for customer_id=1. Run Query plan after the script to inspect the final SELECT.','CREATE INDEX idx_orders_customer ON orders(customer_id); SELECT id,quantity FROM orders WHERE customer_id=1'],
 ['Create idx_products_category on products(category), then return name and price for Tech products.','CREATE INDEX idx_products_category ON products(category); SELECT name,price FROM products WHERE category=\'Tech\'']
],['CREATE INDEX index_name ON table(column).','In lab mode Query plan runs setup statements, then explains the final SELECT.'],'SQL Server clustered/nonclustered and columnstore indexes have different storage details from SQLite indexes.',[28],'lab');
extension('SARGable ranges, not speed commandments',8,'stream','A direct range on an indexed column can permit an efficient lookup. Wrapping that column in a function can prevent a normal index lookup; expression indexes are a separate option. Compare real plans and preserve the result. OR, correlated subqueries, and joins are not universally slow.','CREATE INDEX idx_watch_time ON watch_events(watched_at);\nSELECT id,watched_at FROM watch_events\nWHERE watched_at>=\'2025-01-01\' AND watched_at<\'2025-02-01\';',[
 ['Create idx_watch_time on watched_at; return id and watched_at for Jan 2025 using a half-open timestamp range.','CREATE INDEX idx_watch_time ON watch_events(watched_at); SELECT id,watched_at FROM watch_events WHERE watched_at>=\'2025-01-01\' AND watched_at<\'2025-02-01\''],
 ['Create idx_watch_time on watched_at; return id and watched_at for Jan 1–7 2025 inclusive, using a half-open range.','CREATE INDEX idx_watch_time ON watch_events(watched_at); SELECT id,watched_at FROM watch_events WHERE watched_at>=\'2025-01-01\' AND watched_at<\'2025-01-08\'']
],['Use >= start and < the next boundary without wrapping watched_at.','Inspect the plan; do not infer speed just from the SQL spelling.'],'SARGability makes an index strategy possible; statistics, selectivity, and workload determine whether it wins.',[39,66],'lab');
extension('Partitioning & workload trade-offs',8,'warehouse','Partitioning splits a large table by a defined key. It can aid pruning and lifecycle management, but is not a universal query accelerator. SQLite has no SQL Server partition function/scheme. Practice time-aligned filtering here; use the reference notes to understand native warehouse partitioning.','SELECT sale_key,order_date,sales FROM fact_sales\nWHERE order_date>=\'2025-02-01\' AND order_date<\'2025-03-01\';',[
 ['Return sale_key, order_date and sales for Feb 2025 from fact_sales. Use a half-open range.','SELECT sale_key,order_date,sales FROM fact_sales WHERE order_date>=\'2025-02-01\' AND order_date<\'2025-03-01\''],
 ['Return month (YYYY-MM) and sales (sum) by month from fact_sales.','SELECT strftime(\'%Y-%m\',order_date) AS month,SUM(sales) AS sales FROM fact_sales GROUP BY month']
],['The filter should align with the hypothetical date partition key.','Inspect time boundaries and the result; there are no physical partitions in this engine.'],'Partitioning and clustering are different. Do not report partition elimination from a SQLite plan.',[39]);
extension('Bronze: inspect raw data before cleaning',9,'warehouse','Bronze preserves source records for traceability. Profile missing keys, duplicates, dates, and type mismatches before writing cleaning rules. Do not silently erase rows without documenting why. These source rows are fictional, inspired by common CRM/catalog/sales issues.','SELECT TRIM(raw_id) AS customer_id,COUNT(*) AS versions\nFROM bronze_customers WHERE raw_id IS NOT NULL\nGROUP BY TRIM(raw_id) HAVING COUNT(*)>1;',[
 ['Return customer_id (trimmed raw_id) and versions for non-NULL duplicate customer keys in bronze_customers. Keep only keys with more than one version.','SELECT TRIM(raw_id) AS customer_id,COUNT(*) AS versions FROM bronze_customers WHERE raw_id IS NOT NULL GROUP BY TRIM(raw_id) HAVING COUNT(*)>1'],
 ['Return row_id and order_date for bronze sales whose date is invalid (date(order_date) IS NULL).','SELECT row_id,order_date FROM bronze_sales WHERE date(order_date) IS NULL']
],['Normalize a key for profiling without changing the original rows.','Use a group count for duplicates and date(...) IS NULL for the provided invalid-date case.'],'A date parse check is not a complete calendar validation policy; production rules must also define format and acceptable ranges.',[44,39]);
const silverSQL="CREATE TEMP TABLE silver_customers AS WITH ranked AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY TRIM(raw_id) ORDER BY updated_at DESC) AS rn FROM bronze_customers WHERE raw_id IS NOT NULL AND TRIM(raw_id)<>'') SELECT TRIM(raw_id) AS customer_id,TRIM(name) AS name,CASE UPPER(TRIM(country)) WHEN 'US' THEN 'United States' WHEN 'USA' THEN 'United States' WHEN 'UK' THEN 'United Kingdom' WHEN 'GB' THEN 'United Kingdom' WHEN 'IND' THEN 'India' WHEN 'CA' THEN 'Canada' ELSE UPPER(TRIM(country)) END AS country FROM ranked WHERE rn=1;";
extension('Silver: clean, map & deduplicate',9,'warehouse','Silver applies explicit quality rules. Normalize keys and text, keep the latest customer version, map country codes, and exclude missing keys. With equal version timestamps production logic needs an additional reliable tie-breaker; this sample has none.',''+silverSQL+'\nSELECT customer_id,name,country FROM silver_customers;',[
 ['Create TEMP silver_customers: trim keys/names; discard NULL/empty keys; keep latest updated_at per trimmed key. Map US/USA→United States, GB/UK→United Kingdom, IND→India, CA→Canada. Return customer_id,name,country.',''+silverSQL+' SELECT customer_id,name,country FROM silver_customers'],
 ['Create the same TEMP silver_customers, then return country and customer_count per mapped country.',''+silverSQL+' SELECT country,COUNT(*) AS customer_count FROM silver_customers GROUP BY country']
],['ROW_NUMBER partitions on the normalized natural key.','Keep rn=1, then trim and map the surviving rows.'],'Keep the source unchanged and make exclusion rules visible. A new surrogate key is not a substitute for deduplication.',[69,44],'lab');
const goldSQL="CREATE TEMP TABLE built_fact AS SELECT b.row_id AS sale_key,c.customer_key,p.product_key,CAST(b.quantity AS INTEGER) AS quantity,CAST(b.quantity AS INTEGER)*p.price AS sales,b.order_date FROM bronze_sales b JOIN dim_customer c ON c.customer_id=TRIM(b.customer_id) JOIN dim_product p ON p.product_id=TRIM(b.product_id) WHERE TRIM(b.quantity)<>'' AND TRIM(b.quantity) NOT GLOB '*[^0-9]*' AND CAST(b.quantity AS INTEGER)>0 AND b.order_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date(b.order_date,'+0 days')=b.order_date;";
extension('Gold: dimensions, facts & quality gates',9,'warehouse','Gold presents business entities and measures. Dimensional surrogate keys come from the existing dimension lookup, not a new ROW_NUMBER on every load. One fact row is one sales line. For this exercise reject unknown keys, invalid dates, and nonpositive/nonnumeric quantities; recompute sales from quantity × catalog price.',''+goldSQL+'\nSELECT * FROM built_fact;',[
 ['Build TEMP built_fact from bronze_sales and dimension lookups. Validate numeric positive quantity, valid date and matching trimmed natural keys. Recompute sales = quantity × dim_product.price. Return sale_key,customer_key,product_key,quantity,sales,order_date.',''+goldSQL+' SELECT sale_key,customer_key,product_key,quantity,sales,order_date FROM built_fact'],
 ['Build the same TEMP built_fact; return rejected_rows as source row count minus built fact row count.',''+goldSQL+' SELECT (SELECT COUNT(*) FROM bronze_sales)-(SELECT COUNT(*) FROM built_fact) AS rejected_rows']
],['Join trimmed natural keys to stable dimension lookup keys.','Check text with NOT GLOB before CAST; CAST(bad AS INTEGER) by itself is not validation.'],'Recomputed sales is a declared business rule here, not a universally valid correction to source accounting data.',[70,56],'lab');
extension('EDA: explore before telling the story',9,'warehouse','Start with schema, dimension categories, date coverage, measures, and grain. COUNT(DISTINCT sale_key) counts sales lines in this model, not a missing order-header identifier. Define what a metric counts before putting it into a report.','SELECT MIN(order_date) AS first_sale,MAX(order_date) AS last_sale,\nCOUNT(*) AS sales_lines,SUM(sales) AS total_sales FROM fact_sales;',[
 ['Return first_sale, last_sale, sales_lines and total_sales as one summary row from fact_sales.','SELECT MIN(order_date) AS first_sale,MAX(order_date) AS last_sale,COUNT(*) AS sales_lines,SUM(sales) AS total_sales FROM fact_sales'],
 ['Return metric and value using UNION ALL for Total sales (sum of sales), Units (sum of quantity), and Active customers (distinct customer_key) from fact_sales.','SELECT \'Total sales\' AS metric,SUM(sales) AS value FROM fact_sales UNION ALL SELECT \'Units\',SUM(quantity) FROM fact_sales UNION ALL SELECT \'Active customers\',COUNT(DISTINCT customer_key) FROM fact_sales']
],['Calculate coverage before assuming a complete history.','UNION ALL can turn different measures into a two-column report.'],'Sales-line count and order count are different when an order contains several lines.',[71]);
extension('Customer & product reporting contracts',9,'warehouse','A reusable report combines identity, totals, dates, and meaningful segmentation at one entity grain. Preserve entities with no sales when requested. These exercises define recency against 2025-04-01 rather than today, so the answer is reproducible.','SELECT c.customer_id,c.name,COUNT(f.sale_key) AS sales_lines,\nCOALESCE(SUM(f.sales),0) AS total_sales FROM dim_customer c\nLEFT JOIN fact_sales f ON f.customer_key=c.customer_key\nGROUP BY c.customer_key,c.customer_id,c.name;',[
 ['Return customer_id,name,sales_lines,total_sales,recency_days for every dim_customer. Missing sales total=0; recency=NULL with no sales. Recency = days from last order_date to 2025-04-01, integer.','SELECT c.customer_id,c.name,COUNT(f.sale_key) AS sales_lines,COALESCE(SUM(f.sales),0) AS total_sales,CAST(julianday(\'2025-04-01\')-julianday(MAX(f.order_date)) AS INTEGER) AS recency_days FROM dim_customer c LEFT JOIN fact_sales f ON f.customer_key=c.customer_key GROUP BY c.customer_key,c.customer_id,c.name'],
 ['Return product_id,name,total_sales,total_units,performance_segment for every dim_product. Missing totals=0. High if total_sales>=200, otherwise Standard.','SELECT p.product_id,p.name,COALESCE(SUM(f.sales),0) AS total_sales,COALESCE(SUM(f.quantity),0) AS total_units,CASE WHEN COALESCE(SUM(f.sales),0)>=200 THEN \'High\' ELSE \'Standard\' END AS performance_segment FROM dim_product p LEFT JOIN fact_sales f ON f.product_key=p.product_key GROUP BY p.product_key,p.product_id,p.name']
],['Use LEFT JOIN to preserve zero-activity dimensions.','COUNT(f.sale_key) ignores unmatched NULL rows.'], 'These are report contracts, not inferred customer lifetime value. Segmentation thresholds are exercise-specific.',[72,15]);
extension('Monthly change & cumulative reports',9,'warehouse','Aggregate to monthly grain before using LAG or a running SUM. A percentage change needs a nonzero prior value. This report uses observed months; a complete calendar would be required if missing months should appear as zero.','WITH monthly AS(SELECT strftime(\'%Y-%m\',order_date) AS month,\nSUM(sales) AS sales FROM fact_sales GROUP BY month)\nSELECT month,sales,SUM(sales) OVER(ORDER BY month ROWS\nUNBOUNDED PRECEDING) AS running_sales FROM monthly;',[
 ['Return month (YYYY-MM),sales,running_sales for observed months; cumulative sales ordered by month. Sort output by month.','WITH monthly AS(SELECT strftime(\'%Y-%m\',order_date) AS month,SUM(sales) AS sales FROM fact_sales GROUP BY month) SELECT month,sales,SUM(sales) OVER(ORDER BY month ROWS UNBOUNDED PRECEDING) AS running_sales FROM monthly ORDER BY month',true],
 ['Return month,sales,previous_sales,change_pct for observed months. Compare to previous observed month; percentage rounded to 2 decimals, NULL with no/nonzero denominator. Sort by month.','WITH monthly AS(SELECT strftime(\'%Y-%m\',order_date) AS month,SUM(sales) AS sales FROM fact_sales GROUP BY month),compared AS(SELECT *,LAG(sales) OVER(ORDER BY month) AS previous_sales FROM monthly) SELECT month,sales,previous_sales,ROUND(100.0*(sales-previous_sales)/NULLIF(previous_sales,0),2) AS change_pct FROM compared ORDER BY month',true]
],['The window operates on grouped monthly rows, not original sales lines.','Use NULLIF(previous_sales,0) in the denominator.'],'The first month has no prior observation; zero change would misrepresent that absence.',[72,24,23]);
extension('Review AI-generated SQL with evidence',8,'ai','Use assistance to explain or propose alternatives, then verify against the schema, metric definition, edge cases, and real execution plan. A confident answer can still double-count rows or omit zero-activity users. This lesson is a deterministic review exercise; no live AI service is connected.','-- Review claim: COUNT(*) after LEFT JOIN counts each account’s requests.\n-- Counterexample: accounts with no requests get one preserved row.\nSELECT a.id,COUNT(r.id) AS request_count FROM ai_accounts a\nLEFT JOIN ai_requests r ON r.account_id=a.id GROUP BY a.id;',[
 ['Fix the proposed COUNT(*) LEFT JOIN query. Return id and request_count for every account, including zero-request accounts.','SELECT a.id,COUNT(r.id) AS request_count FROM ai_accounts a LEFT JOIN ai_requests r ON r.account_id=a.id GROUP BY a.id'],
 ['Fix an AI query that divides integers or filters out inactive accounts. Return id and success_pct for every account, NULL with no requests, 2 decimals.','SELECT a.id,ROUND(100.0*SUM(CASE WHEN r.status=\'success\' THEN 1 ELSE 0 END)/NULLIF(COUNT(r.id),0),2) AS success_pct FROM ai_accounts a LEFT JOIN ai_requests r ON r.account_id=a.id GROUP BY a.id']
],['Find a concrete counterexample in the data, not just a stylistic complaint.','Count the nullable right-side id and protect zero denominators.'],'Inspect plans before claiming an optimization; this app does not invoke ChatGPT or another model.',[32,49]);
