moduleQuizzes.push(
 {q:'Which object materializes its result for the current connection?',options:['A normal view','A temporary table created AS SELECT','A SQL Server CTE'],correct:1,why:'A temp table stores intermediate rows. A view stores a query definition; SQL Server CTEs are not materialized results.'},
 {q:'An index changes SCAN to SEARCH on a tiny example. What can you conclude?',options:['Production latency improved by a known percentage','The optimizer chose a different access path; measure the real workload next','Every query needs this index'],correct:1,why:'A plan provides strategy evidence. Timing, reads, selectivity, and write overhead require workload measurement.'},
 {q:'What is the grain of Northstar’s fact_sales?',options:['One customer','One sales line','One calendar month'],correct:1,why:'Each sale_key identifies one line. Aggregate only after deciding the reporting grain.'}
);
Object.assign(specificQuizzes,{58:{q:'Which command changes structure rather than row contents?',options:['ALTER TABLE','UPDATE','DELETE'],correct:0,why:'ALTER is DDL; UPDATE and DELETE modify row contents.'},60:{q:'Does CHECK(quantity>=0) alone forbid NULL in SQLite?',options:['Yes','No; also use NOT NULL when missing quantity is invalid','Only when an index exists'],correct:1,why:'CHECK passes NULL. NOT NULL is a separate constraint.'},61:{q:'After ROLLBACK TO a savepoint, what happens to earlier transaction changes?',options:['They remain pending in the transaction','All are deleted','They are automatically committed'],correct:0,why:'A savepoint rollback undoes only later changes. COMMIT or full ROLLBACK still controls the transaction.'},65:{q:'Can SQLite execute CREATE PROCEDURE from the T-SQL reference?',options:['Yes, unchanged','No; this lesson’s procedure wrapper is SQL Server reference only','Only with a CTE'],correct:1,why:'The SQLite engine lacks stored procedures. Practice the retrieval contract here and the wrapper in SQL Server.'},68:{q:'Does this SQLite example prove physical partition elimination?',options:['Yes','No; it has no SQL Server native partitions','Only if the result has one month'],correct:1,why:'A time predicate is transferable; physical partition schemes and pruning are engine-specific.'},70:{q:'Should a warehouse assign customer surrogate keys with fresh ROW_NUMBER on every load?',options:['Yes, keys should change as row order changes','No; persist stable keys or use an existing dimension lookup','Only if a view is used'],correct:1,why:'Re-numbering can break historical fact relationships. The project uses established dimension lookup keys.'}});
const dialectGuide=[['Limit output','SELECT ... LIMIT 10','SELECT TOP (10) ...','LIMIT 10 or FETCH FIRST 10 ROWS ONLY'],['Monthly bucket',"strftime('%Y-%m', date_column)","DATETRUNC(month, date_column)","DATE_TRUNC('month', date_column)"],['Add seven days',"date(date_column,'+7 days')",'DATEADD(day,7,date_column)',"date_column + INTERVAL '7 days'"],['String length','length(value)','LEN(value) · ignores trailing spaces','LENGTH(value)'],['Replace NULL','COALESCE(a,b)','COALESCE(a,b) / ISNULL(a,b)','COALESCE(a,b)'],['Materialize temp rows','CREATE TEMP TABLE t AS SELECT ...','SELECT ... INTO #t','CREATE TEMP TABLE t AS SELECT ...'],['Stored procedure','Not supported','CREATE PROCEDURE / EXEC','CREATE PROCEDURE / CALL · syntax differs'],['Partitioning','No native SQL Server-style partitions','Partition function + scheme','Declarative table partitioning']];
