const planComparisons=[{title:'Function filter versus a date range',question:'Same January result, different access paths.',cases:[{label:'Function on the indexed column',query:"CREATE INDEX idx_time ON watch_events(watched_at); SELECT id,watched_at FROM watch_events WHERE strftime('%Y-%m',watched_at)='2025-01';",plan:"CREATE INDEX idx_time2 ON watch_events(watched_at); EXPLAIN QUERY PLAN SELECT id,watched_at FROM watch_events WHERE strftime('%Y-%m',watched_at)='2025-01';"},{label:'Half-open range',query:"CREATE INDEX idx_time ON watch_events(watched_at); SELECT id,watched_at FROM watch_events WHERE watched_at>='2025-01-01' AND watched_at<'2025-02-01';",plan:"CREATE INDEX idx_time2 ON watch_events(watched_at); EXPLAIN QUERY PLAN SELECT id,watched_at FROM watch_events WHERE watched_at>='2025-01-01' AND watched_at<'2025-02-01';"}]},{title:'No supporting index versus an index',question:'The result is unchanged; compare SCAN and SEARCH.',cases:[{label:'Without a customer index',query:'SELECT id,quantity FROM orders WHERE customer_id=1;',plan:'EXPLAIN QUERY PLAN SELECT id,quantity FROM orders WHERE customer_id=1;'},{label:'With a customer index',query:'CREATE INDEX idx_customer ON orders(customer_id); SELECT id,quantity FROM orders WHERE customer_id=1;',plan:'EXPLAIN QUERY PLAN SELECT id,quantity FROM orders WHERE customer_id=1;'}]}];
planComparisons.forEach(p=>p.cases.forEach(c=>c.plan=c.plan.slice(c.plan.indexOf('EXPLAIN'))));
